package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }

    @Test
    public void testValueTrue() throws IOException {
        // Test writing true value
        jsonWriter.beginObject();
        jsonWriter.name("isActive");
        JsonWriter result = jsonWriter.value(true);
        jsonWriter.endObject();
        jsonWriter.flush();

        String expected = "{\"isActive\":true}";
        assertEquals(expected, out.toString());
        assertNotNull(result);
    }








}

