package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }







    @Test
    public void testFluentInterface() throws IOException {
        // Test that the method returns the same instance (fluent API)
        jsonWriter.beginObject();
        jsonWriter.name("a");
        JsonWriter returnedWriter = jsonWriter.value(true);

        assertTrue("Method should return the same JsonWriter instance", returnedWriter == jsonWriter);
    }


}

package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }









    @Test
    public void testValueWithIndentation() throws IOException {
        // Test that value works correctly with indentation set
        jsonWriter.setIndent("  ");
        jsonWriter.beginObject();
        jsonWriter.name("test");
        jsonWriter.value(true);
        jsonWriter.endObject();
        jsonWriter.flush();

        // Depending on Gson version, indentation might vary, 
        // but we verify the content is correctly written.
        String result = out.toString();
        assertTrue(result.contains("true"));
        assertTrue(result.contains("\"test\""));
    }
}
